tool_input.command:
node --input-type=module -e "
const h = /^(?:[a-z0-9]+(?:-[a-z0-9]+)+: )?(\w*)(?:\((.*)\))?!?: (.*)\$/;
const b = /^(?:[a-z0-9]+(?:-[a-z0-9]+)+: )?(\w*)(?:\((.*)\))?!: (.*)\$/;
const cases = [
 'build-agent: feat: add forgeProviders assembly',
 'review-patch-agent: fix: correct token resolution',
 'plan-orchestrator: chore: expand README',
 'document-agent: docs: document package build',
 'feat: add worktree probe',
 'chore: bump deps',
 'build-agent: feat(git): scoped subject',
 'feat: fix: colon in the subject',
 'build-agent: feat!: drop legacy layer',
 'feat(git)!: rename export',
 'Merge pull request #6 from paysdoc/branch',
];
for (const c of cases) {
  const m = h.exec(c);
  console.log(JSON.stringify(c), '=> header:', m ? \`type=\${m[1]} scope=\${m[2]} subject=\${JSON.stringify(m[3])}\` : 'NO MATCH', '| breaking:', b.test(c));
}
"
